We assume that we are given a finite set of samples $\{r_i\}_{i=1}^n$ drawn independently from 
\begin{equation} \mathcal{M}_\sigma \stackrel{\bigtriangleup}{=} \{q\in \mathbb{R}^D ~|~ dist(q, \mathcal{M}) < \sigma \}
	,\end{equation}
a tubular neighborhood of $\mathcal{M}$.
Explicitly, we assume that $r_i \sim \operatorname{Unif}(\mathcal{M}_\sigma)$, which is the uniform distribution on $\mathcal{M}_\sigma$; i.e., the normalized Lebesgue measure with respect to $\mathbb{R}^D$.

Finally, let $p\in\mathcal{M}$, we wish to describe $W_p \subset \mathcal{M}$ a neighborhood of $p$ as a graph of a function 
\begin{equation}
	\varphi_p:W_{T_p\mathcal{M}}\to \mathcal{M} \end{equation}
where $W_{T_p\mathcal{M}} = Proj_{T_p\mathcal{M}}(W_p)$, the projection of $W_p$ onto the tangent, and $\varphi_p$ is defined by
\begin{equation}
	\varphi_p(x) = p+(x,\phi_p(x))_{T_p\mathcal{M}} ,\end{equation}
where $x\in \mathbb{R}^d \simeq T_p\mathcal{M}$, $\phi_p(x)\in \mathbb{R}^{D-d} \simeq T_p\mathcal{M}^\perp $, and $(x,y)_{T_p\mathcal{M}} \in \mathbb{R}^D$ denotes that $x\in\mathbb{R}^d$ and $y\in\mathbb{R}^{D-d}$ represent a point in some basis of $T_p\mathcal{M}$ and $T_p\mathcal{M}^\perp$ correspondingly.

Then, we define the graph of $\phi_p$ to be
\begin{equation} \Gamma_{\phi_p, W_p} \stackrel{\bigtriangleup}{=} \{p + (x, \phi_p(x))_{T_p\mathcal{M}} | x\in W_{T_p\mathcal{M}} \}  
	.\end{equation}

Given a point $r\in\mathcal{M}_\sigma$ we limit the the region of interest (ROI) to:
\begin{equation} U_{\textrm{ROI}} = {\{r_i|\operatorname{dist}(r_i,r)<\sqrt{\sigma\tau}\}}
	,\end{equation}
and denote the number of samples in the ROI by $N$.

Then, we define the relevant coordinate system as the pair $(q, H)\in \mathbb{R}^D\times Gr(d, D)$, which minimizes the functional:
\begin{equation} J_1(r; q, H) = \frac{1}{N}\sum_{r_i\in U_{\textrm{ROI}}} \operatorname{dist}^2 (r_i - q,H)
\end{equation}
under the constraints
\begin{enumerate}
	\item Orthogonality: $ r - q\perp H $.
	\item Region of interest: $ r_i \in U_{\textrm{ROI}} $.
	\item Search region: $\norm{r-q} < 2\sigma$.
\end{enumerate}
Explicitly, we denote
\begin{equation} q^*(r), H^*(r) = \arg\!\min_{\substack{ q, H \\ r-q \perp H \\ \|r- q\|<2\sigma}} J_1(r; q, H)
\end{equation}

\caption{Step 1: Find an initial coordinate system} \begin{algorithmic}[1]
		\Statex {\bfseries Input:}\begin{tabular}[t]{ll}
			$\{r_i\}_{i=1}^n\subset \mathcal{M}_\sigma$ & noisy samples of a $d$ dimensional manifold $ \mathcal{M} $.\\
			$r\in \mathcal{M}_\sigma$ & a point in a tubular neighborhood of $\mathcal{M}$.\\
            $d$ & The dimension of the manifold $\mathcal{M}$.\\
            $\tau$ & lower bound on the reach of $\mathcal{M}$. \\
            $\sigma$ & upper bound on the noise level.\\

		\end{tabular}
		\Statex {\bfseries Output:}\begin{tabular}[t]{ll}
			$q^*$ & crude estimation of $p = Proj_{\mathcal{M}}(r)$.\\
			$H^*$ & estimation of $T_p\mathcal{M}$.\\
		\end{tabular}
		\State Disregard points outside of $U_{\textrm{ROI}}$ (plugging $\tau_\text{bound}, \sigma_\text{bound}$ into Eq. \eqref{eq:ROI_clean}).
		\State Find $q^*, H^*$ minimizing \eqref{eq:argmin1_clean} subject to $\norm{q^* - r}<2\sigma$ and $r - q^* \perp H^*$. 
	\end{algorithmic}

Given $(q, H)\in \mathbb{R}^D\times Gr(d,D)$ we define the following minimization scheme, known as local polynomial regression (e.g., \cite{cleveland1979robust,mclain1976two}):
Find $\pi\in \Pi_{k-1}^{d\mapsto D}$ a polynomial of total degree $deg(\pi)\leq k-1$ from $\mathbb{R}^d$ to $\mathbb{R}^{D-d}$ which minimizes
\begin{equation} J_2(\pi ~|~ q, H) = \frac{1}{N_{q, H}}\sum_{r_i \in U_{\textrm{ROI}}^n} \norm{r_i - (x_i, \pi(x_i))_H}^2
	,\end{equation}
where $x_i\in \mathbb{R}^d$ are the projections of $r_i - q$ onto $H$, $(x, y)_H\in \mathbb{R}^d\times\mathbb{R}^{D-d}$ are coefficients in a basis of $H\times H^\perp$, $U_{\textrm{ROI}}^n(q,H)$ is defined through a bandwidth $\epsilon_n$ as
\begin{equation} U_{\textrm{ROI}}^n(q,H) = {\{r_i\in U_\textrm{ROI}~|~\norm{x_i}<\epsilon_n\}}
	,\end{equation}
and $N_{q, H}$ denotes the number of samples in $U_{\textrm{ROI}}^n(q, H)$.
Explicitly, the local polynomial regression is defined through
\begin{equation} \pi^*_{q, H} = \arg\!\min_{\pi\in \Pi_{k-1}^{d\mapsto D}} J_2(\pi ~|~ q, H)
	.\end{equation}

As required to ensure convergence in probability for local polynomial regression \cite{aizenbud2021VectorEstimation,stone1980optimal}, we demand that the bandwidth $\epsilon_n\to 0$ as $n\to\infty$ is such that 
\begin{equation} 0<\lim_{n\rightarrow\infty}n^{1/(2k+d)}\cdot \epsilon_n < \infty
	.\end{equation}

In other words, we look at the manifold as a local graph of a function 
\begin{equation}
	f_{\ell}:\mathbb{R}^d\simeq H_\ell \to \mathbb{R}^{D-d} \simeq H_\ell ^\perp 
	.\end{equation}

Following this, we define 
\begin{equation} f_{\ell+1}:(r, H_{\ell+1}) \to H_{\ell+1} ^\perp \simeq \mathbb{R}^{D-d}    
\end{equation}

Finally, after performing $\kappa$ iterations we get the estimate for $ p\in \mathcal{M}$ and $ T_{ p}\mathcal{M} $ by 
\begin{equation}
	\hat p_n \stackrel{\bigtriangleup}{=} (0, \pi^*_{r, H_\kappa}(0))_{r, H_\kappa} ,\quad \widehat{T_{\hat p_n}\mathcal{M}} \stackrel{\bigtriangleup}{=} H_\kappa
	.\end{equation}

\caption{Step 2: estimating the manifold from a good initial guess} \begin{algorithmic}[1]
		\State {\bfseries Input:}\begin{tabular}[t]{ll}
			$\{r_i\}_{i=1}^n\subset \mathcal{M}_\sigma$ & Noisy samples of a $d$ dimensional manifold $ \mathcal{M} $.\\
            $d$ & The dimension of the manifold $\mathcal{M}$.\\

			$r\in \mathcal{M}_\sigma$ & a point in the tubular neighborhood of $\mathcal{M}$\\

			$H_0$ & Initial approx. of the tangent

		\end{tabular}
		\State {\bfseries Output:}\begin{tabular}[t]{ll}
			$\hat p_n$ & Estimation of $Proj_{\mathcal{M}}(r)\in \mathcal{M}$ .\\
			$\widehat{T_{\hat p_n}\mathcal{M}}$ & Estimation of   $T_{Proj_{\mathcal{M}}(r)}\mathcal{M}$.\\
		\end{tabular}



		\For{$\ell=0$ to $\kappa-1$}
		\State Compute  $\pi^*_{r,H_{\ell}}$ through a version of linear least-squares minimization  \eqref{eq:pi_star_median_trick}.
		\State Compute $ \mathcal{D}_{\pi^*_{r,H_{\ell}}}[0] $ the differential of  $\pi^*_{r,H_{\ell}}$ in some basis at zero.
		\State $H_{\ell+1} = \mathrm{Im}(\mathcal{D}_{\pi^*_{r,H_{\ell}}}[0]) $ \Comment{this is the column space of $ \mathcal{D}_{\pi^*_{r,H_{\ell}}}[0] $}.


		\EndFor 
		\State $\hat p_n = r + (0, \pi^*_{r, H_{\kappa}}(0))^T$ 

		\State $\widehat{T_{\hat p_n}\mathcal{M}} = H_\kappa $
		\State\Return $\hat p_n$ and $\widehat{T_{\hat p_n}\mathcal{M}}$.
	\end{algorithmic}

\caption{Step 1: in practice} \begin{algorithmic}[1]
\State {\bfseries Input:} $\lbrace r_i \rbrace_{i=1}^N, r, d, \tau, \sigma,\epsilon$
\State{\bfseries Output:}\begin{tabular}[t]{ll}
                         $q$ - an $n$ dimensional vector \\
                         $U$ - an $n\times d$ matrix whose columns are $\lbrace u_j \rbrace_{j=1}^d$ 
                         \end{tabular}
                         \Comment{$H = q + Span\lbrace u_j \rbrace_{j=1}^d$}
\State define $R$ to be an $n\times N$ matrix whose columns are $r_i$
\State initialize $U$ with the first $d$ principal components of the spatially weighted PCA \State $q\leftarrow r$
\Repeat
    \State $q_{prev} = q$
    \State $\tilde{R} = (R - repmat(q,1,N))\cdot \Theta$ \Comment{where $\Theta$ is an indicator for points in $U_{\textrm{ROI}}$}
    \State $X_{N\times d} = \tilde{R}^T U$ \Comment{find the representation of $r_i$ in $Col(U)$}
    \State define $\tilde{X}_{N\times (d+1)} = \left[(1,...,1)^T, X\right]$
    \State solve $\tilde{X}^T\tilde{X}\alpha = \tilde{X}^T \tilde{R}^T$ for $\alpha \in M_{(d+1)\times n}$ \Comment{solving the LS minimization of $\tilde{X}\alpha \approx \tilde{R}^T$}
    \State $\tilde{q} = q + \alpha(1,:)^T$
    \State $Q, \hat{R} = qr(\alpha(2:end, :)^T)$ \Comment{where $qr$ denotes the QR decomposition}
    \State $U \leftarrow Q$
    \State $q = \tilde{q} + U U^T (r-\tilde{q})$
\Until {$\|q-q_{\text{prev}}\|<\epsilon$}
\end{algorithmic}

\Repeat
    \State $q_{prev} = q$
    \State $\tilde{R} = (R - repmat(q,1,N))\cdot \Theta$ \Comment{where $\Theta$ is an indicator for points in $U_{\textrm{ROI}}$}
    \State $X_{N\times d} = \tilde{R}^T U$ \Comment{find the representation of $r_i$ in $Col(U)$}
    \State define $\tilde{X}_{N\times (d+1)} = \left[(1,...,1)^T, X\right]$
    \State solve $\tilde{X}^T\tilde{X}\alpha = \tilde{X}^T \tilde{R}^T$ for $\alpha \in M_{(d+1)\times n}$ \Comment{solving the LS minimization of $\tilde{X}\alpha \approx \tilde{R}^T$}
    \State $\tilde{q} = q + \alpha(1,:)^T$
    \State $Q, \hat{R} = qr(\alpha(2:end, :)^T)$ \Comment{where $qr$ denotes the QR decomposition}
    \State $U \leftarrow Q$
    \State $q = \tilde{q} + U U^T (r-\tilde{q})$

Similar to \eqref{eq:FunctionGraph_init} and using the result of Lemma \ref{lem:M_is_locally_a_fuinction_clean}, we begin by looking at the manifold patch $\mathcal{M} \cap \textrm{Cyl}_{H_0}(p,c_{\pi/4}\tau,\tau/2)$ as the graph of a function $f_{0}:(r,H_0) \simeq\mathbb{R}^d\to\mathbb{R}^{D-d}$; i.e., 
\begin{equation}
	\Gamma_{f_{0}, r,H_0} \stackrel{\bigtriangleup}{=} \{r + (x, f_{0}(x))_{H_0} ~|~ x\in B_{H_0}(0, c_{\pi/4}\tau)\}  
	,\end{equation}
where $\textrm{Cyl}_{H_0}(p,c_{\pi/4}\tau, \tau/2)$ is the $D$-dimensional cylinder with the base $B_H(p, c_{\pi/4}\tau)\subset H_0$ and height $\tau/2$ in any direction on $H_0^\perp$.

To conclude our arguments so far, since $\kappa$ satisfies \eqref{eq:n_bound1}, using the union bound on the events $A_0,\ldots, A_\kappa$  we have that 
	\begin{equation} \Pr\left(\angle_{\max} (T_0 f_{\kappa}, H_{\kappa}) \leq \alpha_0 2^{-\kappa}\right) \geq 1 -  \kappa\delta_1.        
	\end{equation}

\paragraph*{Step (iii):} Denote by $p_{\kappa}=(r,f_\kappa(0))_{r, H_{\kappa}}$, and $\mathrm{\mathbf{p}} = Proj_{\mathcal{M}}(r)$. Applying Lemma \ref{lem:dist_given_angle} we have that 
	\begin{equation} \|\mathrm{\mathbf{p}} - p_{\kappa}\| \leq \frac{\hat C_{d}\ln\left(\frac{1}{\delta}\right) n^{-r_1}\left(\ln\left(\ln(n) \right)\right)^{2r_1}}{\left(\frac{1}{2\sigma(2+\sigma/\tau)}-\frac{c}{\tau} \right)},
	\end{equation}
	with probability of at least $1-\delta$. From Corollary 3 in \cite{boissonnat2017reach}, we have that 
	\begin{equation} \sin \frac{\angle_{\max}(T_{\mathbf{p}}\mathcal{M},Tf_\kappa(0))}{2} \leq \frac{\|\mathrm{\mathbf{p}}-p_\kappa\|}{2\tau}.
	\end{equation}
	or,
	\begin{equation} \angle_{\max}(T_{\mathbf{p}}\mathcal{M},Tf_\kappa(0)) \leq \frac{2\|\mathrm{\mathbf{p}}-p_\kappa\|}{\tau}.
	\end{equation}
	Combining \ref{eq:TPM_Tfk} and \eqref{eq:P_q_dist_bound} we have 
	\begin{equation} \angle_{\max}(T_{\mathbf{p}}\mathcal{M},Tf_\kappa(0))
		\leq \frac{2\hat C_{d}\ln\left(\frac{1}{\delta}\right) n^{-r_1}\left(\ln\left(\ln(n) \right)\right)^{2r_1}}{\tau\left(\frac{1}{2\sigma(2+\sigma/\tau)}-\frac{c}{\tau} \right)} = 
		\frac{2\hat C_{d}\ln\left(
			\frac{1}{\delta}\right) n^{-r_1}\left(\ln\left(\ln(n) \right)\right)^{2r_1}}{\frac{M}{4 + 2/M} -c} 
		,
	\end{equation}
	given events $A_0,\ldots A_\kappa$ hold.
	Note that the expression $\frac{M}{4 + 2/M} -c $ in \eqref{eq:TPM_Tfk_full} grows with $M$.
	Combining \eqref{eq:TPM_Tfk_full} with \eqref{eq:prob_ang_bound_Tfk_Hk}, and using the triangle inequality, we get 
	\begin{equation} \angle_{\max}(T_{\mathbf{p}}\mathcal{M},H_\kappa) \leq C_d \cdot \ln(1/\delta)n^{-r_1} (\ln \ln(n))^{2 r_1}
	\end{equation}
	given events $A_0,\ldots A_\kappa$ hold, where $C_d$ is some general constant. 
	Note that according to Algorithm~\ref{alg:step2_clean}  $\widehat{T_{\hat p_n}\mathcal{M}} = H_\kappa$.

From Corollary 3 in \cite{boissonnat2017reach}, we have that 
	\begin{equation} \sin \frac{\angle_{\max}(T_{\mathbf{p}}\mathcal{M},Tf_\kappa(0))}{2} \leq \frac{\|\mathrm{\mathbf{p}}-p_\kappa\|}{2\tau}.
	\end{equation}
	or,
	\begin{equation} \angle_{\max}(T_{\mathbf{p}}\mathcal{M},Tf_\kappa(0)) \leq \frac{2\|\mathrm{\mathbf{p}}-p_\kappa\|}{\tau}.
	\end{equation}

Combining \eqref{eq:TPM_Tfk_full} with \eqref{eq:prob_ang_bound_Tfk_Hk}, and using the triangle inequality, we get 
	\begin{equation} \angle_{\max}(T_{\mathbf{p}}\mathcal{M},H_\kappa) \leq C_d \cdot \ln(1/\delta)n^{-r_1} (\ln \ln(n))^{2 r_1}
	\end{equation}
	given events $A_0,\ldots A_\kappa$ hold, where $C_d$ is some general constant. 
	Note that according to Algorithm~\ref{alg:step2_clean}  $\widehat{T_{\hat p_n}\mathcal{M}} = H_\kappa$.

For $x\in[0,\sqrt{3}/2]$
\begin{equation} 1-1/2x^2 \geq \sqrt{1 - x^2} \geq 1-x^2
\end{equation}

For $x\in[0,\sqrt{3}/2]$
\begin{equation}
1-1/2x^2-1/8x^4 \geq \sqrt{1 - x^2} \geq 1-\frac{1}{2}x^2 - x^4    
\end{equation}

Let $V$ be an inner product space. Given two sub-spaces $\mathcal{U}, \mathcal{W}$ of dimensions $dim(\mathcal{U})=k, dim(\mathcal{W}) = l$, where $k \leq l$ there exists a sequence of $k$ angles $0 \leq \beta_1 \leq \ldots \leq \beta_k \leq \pi/2$ called the principal angles and their corresponding principal pairs of vectors $(u_i, w_i)\in\mathcal{U}\times\mathcal{W}$ for $i=1,\ldots,k$ such that $\angle(u_i,w_i) = \beta_i$ are defined by: 
	\begin{equation*}
	\begin{array}{ll}
	    u_1, w_1 \stackrel{\bigtriangleup}{=} \arg\!\min\limits_{\substack{u\in\mathcal{U}, w\in\mathcal{W} \\ \norm{u}=\norm{w} =1}}\arccos\left(\abs{\langle u, w \rangle}\right), &
	    \beta_1 \stackrel{\bigtriangleup}{=} \angle(u_1, w_1)
	\end{array}    
	,\end{equation*}
	and for $i > 1$
	\begin{equation*}
	\begin{array}{ll}
	    u_i, w_i \stackrel{\bigtriangleup}{=} \arg\!\min\limits_{\substack{u\perp\mathcal{U}_{i-1}, w\perp\mathcal{W}_{i-1} \\ \norm{u}=\norm{w} =1}}\arccos\left(\abs{\langle u, w \rangle}\right), &
	    \beta_i \stackrel{\bigtriangleup}{=} \angle(u_i, w_i)
	\end{array}
	,\end{equation*}
    where $$\mathcal{U}_i \stackrel{\bigtriangleup}{=} Span\{u_j\}_{j=1}^i ~,~ \mathcal{W}_i \stackrel{\bigtriangleup}{=} Span\{w_j\}_{j=1}^i.$$

In our case, we measure the distance between two subspaces by taking the maximal principal angle (maximal angle) , and denote it as
\begin{equation} \angle_{\max}(\mathcal{U},\mathcal{W}) \stackrel{\bigtriangleup}{=} \max_{1\leq i\leq d}\beta_i
.\end{equation}

