&\leq  \frac{\xi(\wtilde D+1)c_1 \sigma\alpha}{\tau} + \frac{(\wtilde D+1)c_1 \sigma\alpha (1 + 4\alpha^2)^{\wtilde D} }
{\tau}\frac{2}{\xi\sqrt{\wtilde D-2}}e^{-(\wtilde D - 2 )\xi^2/2}
